"""Розбір буклетів Крок 1 (Медицина, укр.) → питання з анатомії → atlas/krok1.js.
Правильна відповідь в офіційних буклетах Центру тестування завжди під літерою A.
python3 tools/krok/parse_krok.py            — розібрати tools/krok/raw/*.txt
"""
import re, os, json, glob, hashlib, unicodedata
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.dirname(os.path.dirname(HERE))
def fix_i(s):   # у PDF латинська i замість кириличної і всередині слів
    s = re.sub(r'(?<=[А-Яа-яЇїЄєҐґ’\'])[iI](?=[А-Яа-яЇїЄєҐґ’\']|\b)', lambda m: 'і' if m.group(0) == 'i' else 'І', s)
    s = re.sub(r'\b[iI](?=[А-Яа-яЇїЄєҐґ])', lambda m: 'і' if m.group(0) == 'i' else 'І', s)
    return s
def clean(s):
    s = fix_i(s.replace('­', ''))
    s = re.sub(r'(\w)-\s*\n\s*(\w)', r'\1\2', s)            # перенос
    s = re.sub(r'\s*\n\s*', ' ', s); s = re.sub(r'\s+', ' ', s).strip()
    # колонтитули буклетів, що потрапили в текст
    s = re.sub(r'\(?\s*(укра[їi]номовн\w*|російськомовн\w*|англійськ\w*|німецьк\w*|французьк\w*)?\s*варіант,?\s*(вітчизняні|іноземн\w*)\s*студенти\)?\s*(\d{4}\s*рік)?\s*\d*', ' ', s, flags=re.I)
    s = re.sub(r'\b(вітчизняні|іноземн\w+) студенти\)?\s*(\d{4} рік)?\s*\d*', ' ', s, flags=re.I)
    s = re.sub(r'\b\d{4} рік\s*\d*\b', ' ', s); s = re.sub(r'\b\d{4,6}uk\b|\b0\d{5}\b', ' ', s)
    s = re.sub(r'Крок 1 Загальна лікарська підготовка\s*\(?[^)]*\)?', ' ', s)
    s = re.sub(r'\s+', ' ', s).strip(' -–—,;')
    return s
def parse(txt):
    lines = [l.rstrip() for l in txt.split('\n')]
    lines = [l for l in lines if not re.fullmatch(r'\s*\d{1,3}\s*', l)]   # номери сторінок
    text = '\n'.join(lines)
    text = re.sub(r'(?m)^\s*(\d{1,3})\s*[\.\)]\s+', lambda m: m.group(1) + '. ', text)   # "1 ." / "1)" → "1. "
    qs = []
    idx = [(m.start(), int(m.group(1))) for m in re.finditer(r'(?m)^(\d{1,3})\. ', text)]
    for k, (pos, n) in enumerate(idx):
        end = idx[k + 1][0] if k + 1 < len(idx) else len(text)
        block = text[pos:end]
        if len(block) > 2500: block = block[:2500]
        m = re.match(r'\d{1,3}\. ', block); body = block[m.end():]
        parts = re.split(r'(?m)^\s*([A-EА-Е])[\.\)]\s', body)
        if len(parts) < 9: continue
        stem = clean(parts[0]); opts = {}
        for i in range(1, len(parts) - 1, 2):
            L = parts[i].translate(str.maketrans('АВСДЕ', 'ABCDE')); opts[L] = clean(parts[i + 1])
        if len(stem) < 15 or len(stem) > 900 or not all(x in opts for x in 'ABCD'): continue
        opts = {k2: v[:300] for k2, v in opts.items() if k2 in 'ABCDE'}
        qs.append({'n': n, 'q': stem, 'options': opts, 'answer': 'A'})
    return qs
