def score(q):
    st = norm_kw(q['q']); tail = st[-200:]
    ask = 1 if (ASK.search(tail) or ASK2.search(tail)) else 0
    lat = sum(1 for o in q['options'].values() if re.search(r'\b(os|ossa|musculus|m\.|mm\.|n\.|nn\.|a\.|aa\.|v\.|vv\.|nervus|nervi|arteria|arteriae|vena|venae|foramen|foramina|canalis|processus|sulcus|fossa|tuberculum|tuber|ductus|plexus|lig\.|ligamentum|fascia|ramus|rami|truncus|nucleus|corpus|caput|cornu|incisura|facies|margo|spina|crista|lobus|gyrus|ventriculus|cavum|cavitas|bursa|recessus|sinus|vagina|ganglion|tractus|fasciculus|articulatio|apertura|hiatus|septum|membrana|tunica|pars|regio|trigonum|angulus|linea|meatus|ostium|valva|capsula)\b', o.lower()))
    neg = sum(1 for k in DISC_NEG if k in st) + sum(1 for k in TAIL_NEG if k in tail)
    pos = sum(1 for k in POS_STRONG if k in st)
    sc = 3 * ask + 1.5 * min(lat, 4) + 0.4 * min(pos, 6) - 2 * neg
    return sc, pos, neg, lat
